import React, { useState, useEffect } from 'react';
import { Modal, Button, Form, Row, Col, ListGroup } from 'react-bootstrap';
import { Interviewer } from '../types';

interface ProfileSettingsModalProps {
  show: boolean;
  onHide: () => void;
  interviewers: Interviewer[];
  updateInterviewer: (interviewer: Interviewer) => void;
  addInterviewer: (interviewer: Omit<Interviewer, 'id'>) => Promise<void>;
  deleteInterviewer: (id: string) => Promise<void>;
}

const NEW_INTERVIEWER_TEMPLATE: Omit<Interviewer, 'id'> = {
  name: '',
  title: '',
  email: '',
};

const ProfileSettingsModal: React.FC<ProfileSettingsModalProps> = ({ 
  show, 
  onHide, 
  interviewers, 
  updateInterviewer, 
  addInterviewer, 
  deleteInterviewer
}) => {
  // 現在選択されている、または編集中の担当者
  const [selected, setSelected] = useState<Interviewer | Omit<Interviewer, 'id'> | null>(null);

  useEffect(() => {
    // モーダルが開いたときに、最初の担当者を選択状態にする
    if (show && interviewers.length > 0) {
      setSelected(interviewers[0]);
    } else {
      setSelected(null);
    }
  }, [show, interviewers]);

  const handleSelect = (interviewer: Interviewer) => {
    setSelected(interviewer);
  };

  const handleAddNew = () => {
    setSelected(NEW_INTERVIEWER_TEMPLATE);
  };

  const handleFieldChange = (field: keyof Interviewer, value: string) => {
    if (selected) {
      setSelected({ ...selected, [field]: value });
    }
  };

  const handleSave = async () => {
    if (!selected) return;

    if ('id' in selected) {
      // IDがある場合は既存の担当者の更新
      updateInterviewer(selected);
    } else {
      // IDがない場合は新規担当者の追加
      await addInterviewer(selected);
    }
    onHide();
  };

  const handleDelete = async () => {
    if (selected && 'id' in selected) {
      if (window.confirm(`${selected.name}さんを削除してもよろしいですか？この担当者に関連するスケジュールもすべて削除されます。`)) {
        await deleteInterviewer(selected.id);
        onHide();
      }
    }
  };

  return (
    <Modal show={show} onHide={onHide} size="lg">
      <Modal.Header closeButton>
        <Modal.Title>プロフィール設定</Modal.Title>
      </Modal.Header>
      <Modal.Body>
        <Row>
          {/* 左カラム：担当者リストと新規追加ボタン */}
          <Col sm={4}>
            <ListGroup>
              {interviewers.map(interviewer => (
                <ListGroup.Item 
                  key={interviewer.id} 
                  action 
                  active={!!(selected && 'id' in selected && selected.id === interviewer.id)}
                  onClick={() => handleSelect(interviewer)}
                >
                  {interviewer.name}
                </ListGroup.Item>
              ))}
            </ListGroup>
            <Button variant="outline-primary" className="mt-3 w-100" onClick={handleAddNew}>
              新規追加
            </Button>
          </Col>

          {/* 右カラム：編集フォーム */}
          <Col sm={8}>
            {selected ? (
              <Form>
                <Form.Group className="mb-3">
                  <Form.Label>名前</Form.Label>
                  <Form.Control
                    type="text"
                    value={selected.name}
                    onChange={(e) => handleFieldChange('name', e.target.value)}
                  />
                </Form.Group>
                <Form.Group className="mb-3">
                  <Form.Label>役職</Form.Label>
                  <Form.Control
                    type="text"
                    value={selected.title}
                    onChange={(e) => handleFieldChange('title', e.target.value)}
                  />
                </Form.Group>
                <Form.Group className="mb-3">
                  <Form.Label>メールアドレス</Form.Label>
                  <Form.Control
                    type="email"
                    value={selected.email}
                    onChange={(e) => handleFieldChange('email', e.target.value)}
                  />
                </Form.Group>
              </Form>
            ) : (
              <div className="text-center text-muted pt-5">担当者を選択するか、新規追加してください。</div>
            )}
          </Col>
        </Row>
      </Modal.Body>
      <Modal.Footer>
        <Button variant="danger" onClick={handleDelete} disabled={!selected || !('id' in selected)}>削除</Button>
        <div className="flex-grow-1"></div>
        <Button variant="secondary" onClick={onHide}>キャンセル</Button>
        <Button variant="primary" onClick={handleSave} disabled={!selected}>保存</Button>
      </Modal.Footer>
    </Modal>
  );
};

export default ProfileSettingsModal;